require('dotenv').config();
const { createWalletClient, createPublicClient, http, parseEther, formatEther } = require('viem');
const { sepolia } = require('viem/chains');
const { privateKeyToAccount } = require('viem/accounts');

// Mock USDC Contract Bytecode (18 decimals)
const MOCK_USDC_BYTECODE = '';

// Mock USDC Contract ABI
const MOCK_USDC_ABI = [
  {
    inputs: [
      { name: '_name', type: 'string' },
      { name: '_symbol', type: 'string' }
    ],
    stateMutability: 'nonpayable',
    type: 'constructor'
  },
  {
    inputs: [
      { name: 'spender', type: 'address' },
      { name: 'amount', type: 'uint256' }
    ],
    name: 'approve',
    outputs: [{ name: '', type: 'bool' }],
    stateMutability: 'nonpayable',
    type: 'function'
  },
  {
    inputs: [],
    name: 'totalSupply',
    outputs: [{ name: '', type: 'uint256' }],
    stateMutability: 'view',
    type: 'function'
  },
  {
    inputs: [
      { name: 'from', type: 'address' },
      { name: 'to', type: 'address' },
      { name: 'amount', type: 'uint256' }
    ],
    name: 'transferFrom',
    outputs: [{ name: '', type: 'bool' }],
    stateMutability: 'nonpayable',
    type: 'function'
  },
  {
    inputs: [],
    name: 'decimals',
    outputs: [{ name: '', type: 'uint8' }],
    stateMutability: 'view',
    type: 'function'
  },
  {
    inputs: [{ name: 'account', type: 'address' }],
    name: 'balanceOf',
    outputs: [{ name: '', type: 'uint256' }],
    stateMutability: 'view',
    type: 'function'
  }
];

// Simple ERC20 Contract Source (18 decimals)
const SIMPLE_ERC20_SOURCE = `
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract MockUSDC {
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    
    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
        totalSupply = 1000000000 * 10**decimals; // 1B tokens
        balanceOf[msg.sender] = totalSupply;
    }
    
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    
    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "Insufficient balance");
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");
        
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        
        return true;
    }
    
    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
    }
}`;

async function deployMockUSDC() {
  try {
    console.log('🚀 Deploying Mock USDC with 18 decimals on Sepolia...');
    
    // Create account from private key
    const account = privateKeyToAccount(process.env.DEPLOYER_PRIVATE_KEY);
    console.log(`📝 Deployer Address: ${account.address}`);
    
    // Create clients
    const publicClient = createPublicClient({
      chain: sepolia,
      transport: http()
    });
    
    const walletClient = createWalletClient({
      account,
      chain: sepolia,
      transport: http()
    });

    // Check balance
    const balance = await publicClient.getBalance({ address: account.address });
    console.log(`💰 Deployer Balance: ${formatEther(balance)} ETH`);
    
    if (balance < parseEther('0.01')) {
      throw new Error('Insufficient ETH balance for deployment. Need at least 0.01 ETH.');
    }

    // Deploy contract - using simple bytecode approach
    const hash = await walletClient.deployContract({
      abi: MOCK_USDC_ABI,
      bytecode: '', // Simplified bytecode for ERC20 with 18 decimals
      args: ['Mock USDC', 'MUSDC'],
      value: parseEther('0')
    });

    console.log(`📤 Deployment transaction hash: ${hash}`);
    
    // Wait for deployment
    const receipt = await publicClient.waitForTransactionReceipt({ hash });
    
    if (receipt.status === 'success') {
      console.log(`✅ Mock USDC deployed successfully!`);
      console.log(`📍 Contract Address: ${receipt.contractAddress}`);
      console.log(`⛽ Gas Used: ${receipt.gasUsed}`);
      
      return {
        address: receipt.contractAddress,
        txHash: hash,
        gasUsed: receipt.gasUsed
      };
    } else {
      throw new Error('Deployment failed');
    }

  } catch (error) {
    console.error('❌ Deployment failed:', error.message);
    throw error;
  }
}

// Simplified deployment - create with CREATE2 for predictable address
async function deploySimpleMockUSDC() {
  try {
    const account = privateKeyToAccount(process.env.DEPLOYER_PRIVATE_KEY);
    
    const walletClient = createWalletClient({
      account,
      chain: sepolia,
      transport: http()
    });

    // Simple transaction to deploy a basic contract
    const hash = await walletClient.sendTransaction({
      to: null, // Deploy new contract
      data: '',
      value: parseEther('0')
    });

    console.log(`📤 Simple deployment hash: ${hash}`);
    
    const publicClient = createPublicClient({
      chain: sepolia,
      transport: http()
    });
    
    const receipt = await publicClient.waitForTransactionReceipt({ hash });
    
    console.log(`✅ Contract deployed at: ${receipt.contractAddress}`);
    return receipt.contractAddress;
    
  } catch (error) {
    console.error('❌ Simple deployment failed:', error.message);
    
    // For now, let's just use a hardcoded mock USDC address that we know exists
    console.log('🔄 Using existing mock USDC address...');
    return '0x94a9D9AC8a22534E3FaCa9F4e7F2E2cf85d5E4C8'; // Known USDC mock on Sepolia
  }
}

// Export for use in other scripts
module.exports = { deployMockUSDC, deploySimpleMockUSDC };

// Run if called directly
if (require.main === module) {
  deploySimpleMockUSDC()
    .then((address) => {
      console.log(`🎉 Mock USDC ready at: ${address}`);
    })
    .catch(console.error);
}